-- Velvet — référentiel France/Belgique, relation membre et activation commerciale Pro.

alter table public.venue_directory
  add column if not exists slug text,
  add column if not exists region text,
  add column if not exists department_or_province text,
  add column if not exists postal_code text,
  add column if not exists category_primary text,
  add column if not exists category_tags text[] not null default '{}',
  add column if not exists relevance_level text,
  add column if not exists audience text,
  add column if not exists evening_types text,
  add column if not exists opening_hours_text text,
  add column if not exists pricing_text text,
  add column if not exists practical_info text,
  add column if not exists amenities text[] not null default '{}',
  add column if not exists booking_url text,
  add column if not exists phone text,
  add column if not exists email citext,
  add column if not exists maps_search_url text,
  add column if not exists business_status text,
  add column if not exists listing_status text,
  add column if not exists source_grade text check (source_grade is null or source_grade in ('A','B','C','D')),
  add column if not exists source_primary_url text,
  add column if not exists source_secondary_urls text[] not null default '{}',
  add column if not exists source_checked_at date,
  add column if not exists manual_review_required boolean not null default true,
  add column if not exists photo_reuse_status text,
  add column if not exists public_visibility text not null default 'listed'
    check (public_visibility in ('listed','hidden','archived')),
  add column if not exists claimed_establishment_id uuid unique
    references public.establishments(id) on delete set null,
  add column if not exists claim_status text not null default 'unclaimed'
    check (claim_status in ('unclaimed','pending','claimed'));

create unique index if not exists venue_directory_slug_idx
  on public.venue_directory(slug) where slug is not null;
create index if not exists venue_directory_public_search_idx
  on public.venue_directory(public_visibility,country_code,kind,lower(name));

alter table public.establishments
  add column if not exists directory_venue_id uuid unique
    references public.venue_directory(id) on delete set null,
  add column if not exists subscription_status text not null default 'inactive'
    check (subscription_status in ('inactive','trial','active','past_due','cancelled'));

create table if not exists public.profile_venue_relationships (
  profile_id uuid not null references public.member_profiles(id) on delete cascade,
  venue_id uuid not null references public.venue_directory(id) on delete cascade,
  relation_type text not null check (relation_type in ('favorite','visited','planning')),
  declared_by uuid not null references public.accounts(user_id) on delete cascade,
  occurred_on date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (profile_id,venue_id,relation_type)
);

alter table public.profile_venue_relationships enable row level security;
drop policy if exists profile_venue_relationships_owner
  on public.profile_venue_relationships;
create policy profile_venue_relationships_owner
on public.profile_venue_relationships
for all to authenticated
using (public.is_profile_member(profile_id))
with check (public.is_profile_member(profile_id) and declared_by=auth.uid());
grant select,insert,update,delete on public.profile_venue_relationships to authenticated;

create table if not exists public.establishment_claims (
  id uuid primary key default gen_random_uuid(),
  venue_id uuid not null references public.venue_directory(id) on delete cascade,
  claimant_user_id uuid not null references public.accounts(user_id) on delete cascade,
  message text,
  evidence jsonb not null default '{}'::jsonb,
  status text not null default 'pending'
    check (status in ('pending','approved','declined','cancelled')),
  reviewed_by uuid references public.accounts(user_id) on delete set null,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists establishment_claims_one_pending_idx
  on public.establishment_claims(venue_id) where status='pending';
alter table public.establishment_claims enable row level security;
drop policy if exists establishment_claims_self_read
  on public.establishment_claims;
create policy establishment_claims_self_read
on public.establishment_claims for select to authenticated
using (claimant_user_id=auth.uid() or public.is_control_user());
drop policy if exists establishment_claims_self_create
  on public.establishment_claims;
create policy establishment_claims_self_create
on public.establishment_claims for insert to authenticated
with check (claimant_user_id=auth.uid());
drop policy if exists establishment_claims_control_update
  on public.establishment_claims;
create policy establishment_claims_control_update
on public.establishment_claims for update to authenticated
using (public.is_control_user()) with check (public.is_control_user());
grant select,insert,update on public.establishment_claims to authenticated;

create or replace function public.set_my_venue_relationship(
  target_profile uuid,
  target_venue uuid,
  target_relation text,
  enabled boolean,
  visit_date date default null
)
returns void
language plpgsql security definer set search_path=''
as $$
begin
  if auth.uid() is null or not public.is_profile_member(target_profile)
    or not public.is_admitted_member() then
    raise exception 'member_profile_required';
  end if;
  if target_relation not in ('favorite','visited','planning') then
    raise exception 'invalid_venue_relationship';
  end if;
  if not exists (
    select 1 from public.venue_directory
    where id=target_venue and public_visibility='listed' and verification_status<>'closed'
  ) then
    raise exception 'venue_unavailable';
  end if;
  if enabled then
    insert into public.profile_venue_relationships(
      profile_id,venue_id,relation_type,declared_by,occurred_on
    ) values (
      target_profile,target_venue,target_relation,auth.uid(),
      case when target_relation='visited' then visit_date else null end
    )
    on conflict(profile_id,venue_id,relation_type) do update
      set occurred_on=excluded.occurred_on,declared_by=auth.uid(),updated_at=now();
  else
    delete from public.profile_venue_relationships
    where profile_id=target_profile and venue_id=target_venue and relation_type=target_relation;
  end if;
end;
$$;
grant execute on function public.set_my_venue_relationship(uuid,uuid,text,boolean,date) to authenticated;

create or replace function public.member_venue_catalog()
returns table (
  id uuid, slug text, name text, kind text, city text, country_code text,
  address_public text, latitude double precision, longitude double precision,
  website text, verification_status text, region text, department_or_province text,
  postal_code text, category_primary text, category_tags text[], relevance_level text,
  audience text, evening_types text, opening_hours_text text, pricing_text text,
  practical_info text, amenities text[], booking_url text, phone text, email text,
  maps_search_url text, business_status text, listing_status text, source_grade text,
  source_primary_url text, source_checked_at date, manual_review_required boolean,
  photo_reuse_status text, claimed_establishment_id uuid, claim_status text,
  favorites_count bigint, visits_count bigint, planning_count bigint
)
language plpgsql stable security definer set search_path=''
as $$
begin
  if auth.uid() is null or not public.is_beta_approved() or not public.is_admitted_member() then
    raise exception 'member_access_required';
  end if;
  return query
  select v.id,v.slug,v.name,v.kind,v.city,v.country_code,v.address_public,
    v.latitude,v.longitude,v.website,v.verification_status,v.region,
    v.department_or_province,v.postal_code,v.category_primary,v.category_tags,
    v.relevance_level,v.audience,v.evening_types,v.opening_hours_text,v.pricing_text,
    v.practical_info,v.amenities,v.booking_url,v.phone,v.email::text,v.maps_search_url,
    v.business_status,v.listing_status,v.source_grade,v.source_primary_url,
    v.source_checked_at,v.manual_review_required,v.photo_reuse_status,
    v.claimed_establishment_id,v.claim_status,
    count(r.venue_id) filter(where r.relation_type='favorite'),
    count(r.venue_id) filter(where r.relation_type='visited'),
    count(r.venue_id) filter(where r.relation_type='planning')
  from public.venue_directory v
  left join public.profile_venue_relationships r on r.venue_id=v.id
  where v.public_visibility='listed' and v.verification_status<>'closed'
  group by v.id
  order by v.name;
end;
$$;
grant execute on function public.member_venue_catalog() to authenticated;

create or replace function public.control_claim_directory_venue(
  target_venue uuid,target_owner uuid
)
returns uuid
language plpgsql security definer set search_path=''
as $$
declare venue_row public.venue_directory; target_id uuid;
begin
  if auth.uid() is null or not (public.has_role('admin') or public.has_role('direction')) then
    raise exception 'control_admin_required';
  end if;
  select * into venue_row from public.venue_directory where id=target_venue for update;
  if venue_row.id is null or venue_row.claimed_establishment_id is not null then
    raise exception 'venue_claim_unavailable';
  end if;
  if not exists(select 1 from public.accounts where user_id=target_owner and status='active') then
    raise exception 'invalid_owner';
  end if;
  insert into public.establishments(
    directory_venue_id,slug,name,kind,description,city,address_public,phone_public,
    email_public,opening_hours,amenities,visibility,subscription_status
  ) values (
    venue_row.id,coalesce(venue_row.slug,'venue-'||replace(venue_row.id::text,'-','')),
    venue_row.name,venue_row.kind,venue_row.practical_info,venue_row.city,
    venue_row.address_public,venue_row.phone,venue_row.email,
    case when venue_row.opening_hours_text is null then '{}'::jsonb
      else jsonb_build_object('public',venue_row.opening_hours_text) end,
    venue_row.amenities,'draft','inactive'
  ) returning id into target_id;
  update public.venue_directory set claimed_establishment_id=target_id,
    claim_status='claimed',updated_at=now() where id=venue_row.id;
  insert into public.establishment_staff(establishment_id,user_id,staff_role,status)
  values(target_id,target_owner,'owner','active');
  insert into public.account_roles(user_id,role_code,granted_by)
  values(target_owner,'pro_owner',auth.uid())
  on conflict(user_id,role_code) do update
    set expires_at=null,granted_by=auth.uid(),granted_at=now();
  insert into public.audit_events(actor_user_id,actor_type,action,entity_type,entity_id,metadata)
  values(auth.uid(),'user','directory_venue_claimed','establishment',target_id,
    jsonb_build_object('venue_id',target_venue,'owner',target_owner,'subscription','inactive'));
  return target_id;
end;
$$;

create or replace function public.control_set_establishment_subscription(
  target_establishment uuid,target_status text
)
returns void
language plpgsql security definer set search_path=''
as $$
begin
  if auth.uid() is null or not (public.has_role('admin') or public.has_role('direction')) then
    raise exception 'control_admin_required';
  end if;
  if target_status not in ('inactive','trial','active','past_due','cancelled') then
    raise exception 'invalid_subscription_status';
  end if;
  update public.establishments set subscription_status=target_status,updated_at=now()
  where id=target_establishment;
  if not found then raise exception 'establishment_not_found'; end if;
  insert into public.audit_events(actor_user_id,actor_type,action,entity_type,entity_id,metadata)
  values(auth.uid(),'user','establishment_subscription_changed','establishment',
    target_establishment,jsonb_build_object('status',target_status));
end;
$$;
grant execute on function public.control_claim_directory_venue(uuid,uuid) to authenticated;
grant execute on function public.control_set_establishment_subscription(uuid,text) to authenticated;

drop policy if exists establishments_staff_write on public.establishments;
create policy establishments_staff_write on public.establishments
for update to authenticated
using (
  public.is_venue_staff(id)
  and subscription_status in ('trial','active')
)
with check (
  public.is_venue_staff(id)
  and subscription_status in ('trial','active')
);

drop policy if exists events_create on public.events;
create policy events_create on public.events
for insert to authenticated with check (
  created_by=auth.uid()
  and (
    (
      owner_type='establishment'
      and public.is_venue_staff(establishment_id)
      and exists (
        select 1 from public.establishments e
        where e.id=establishment_id and e.subscription_status in ('trial','active')
      )
    )
    or
    (
      owner_type='organizer'
      and exists (
        select 1 from public.organizer_profiles op
        where op.id=organizer_profile_id and op.status='approved'
          and public.is_profile_member(op.member_profile_id)
      )
    )
  )
);

drop policy if exists events_update on public.events;
create policy events_update on public.events
for update to authenticated using (
  public.is_control_user()
  or (
    created_by=auth.uid()
    and (
      owner_type='organizer'
      or exists (
        select 1 from public.establishments e
        where e.id=establishment_id and e.subscription_status in ('trial','active')
      )
    )
  )
  or (
    establishment_id is not null
    and public.is_venue_staff(establishment_id)
    and exists (
      select 1 from public.establishments e
      where e.id=establishment_id and e.subscription_status in ('trial','active')
    )
  )
);

drop policy if exists establishment_drafts_staff on public.establishment_drafts;
create policy establishment_drafts_staff
on public.establishment_drafts for all to authenticated
using (
  public.is_venue_staff(establishment_id)
  and exists (
    select 1 from public.establishments e
    where e.id=establishment_id and e.subscription_status in ('trial','active')
  )
)
with check (
  public.is_venue_staff(establishment_id)
  and updated_by=auth.uid()
  and exists (
    select 1 from public.establishments e
    where e.id=establishment_id and e.subscription_status in ('trial','active')
  )
);

